import {escapeHTML as e,imageFile,imageURL,plain} from './store.js';
const frames={arabesque:'assets/cards/arabesque.png',celestial:'assets/cards/celestial.png',none:''};
const hex=(v,d)=>/^#[0-9a-f]{6}$/i.test(v||'')?v:d;
export function cardSettings(item){const saved=item.cardAppearance||{},settings={front:face(saved.front,item.image,'arabesque','#164b39'),back:face(saved.back,'','celestial','#18382e')};if(!Object.hasOwn(saved.back||{},'subtitle'))settings.back.subtitle=settings.front.subtitle;else if(!settings.back.subtitle&&settings.front.subtitle)settings.back.subtitle=settings.front.subtitle;settings.front.subtitle='' ;return settings;}
function face(v={},image,frame,bg){const number=(key,min,max,def)=>Number.isFinite(Number(v[key]))?Math.max(min,Math.min(max,Number(v[key]))):def;return {background:hex(v.background,bg),textColor:hex(v.textColor,'#e0c58f'),fontSize:number('fontSize',24,70,46),frame:Object.hasOwn(frames,v.frame)?v.frame:frame,image:imageURL(v.image??image),scale:number('scale',.5,2,1),zoom:number('zoom',1,3,1),x:number('x',-100,100,0),y:number('y',-100,100,0),subtitle:String(v.subtitle||'').slice(0,220)};}
const cache=new Map();function load(src){if(!src)return Promise.resolve(null);if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>{cache.delete(src);reject(Error('Não foi possível carregar a imagem da carta.'));};im.src=src;}));return cache.get(src);}
export async function drawCard(canvas,settings,name,side,width=600){
 const [portrait,frameImage]=await Promise.all([load(settings.image),load(frames[settings.frame])]);canvas.width=width;canvas.height=width*1.5;const c=canvas.getContext('2d');c.scale(width/600,width/600);c.fillStyle=settings.background;c.fillRect(0,0,600,900);
 if(portrait){c.save();c.beginPath();c.roundRect(60,48,480,680,36);c.clip();const factor=Math.max(480/portrait.width,680/portrait.height)*settings.scale*settings.zoom,w=portrait.width*factor,h=portrait.height*factor;c.drawImage(portrait,300-w/2+settings.x*2.4,388-h/2+settings.y*3.4,w,h);c.restore();}
 if(frameImage)c.drawImage(frameImage,24,12,552,876);
 c.fillStyle=settings.textColor;c.textAlign='center';c.textBaseline='middle';
 function textBox(text,cy,size,maxWidth,maxHeight,maxLines){
  let lines=[];for(;size>=16;size--){c.font=`${size}px Georgia`;lines=[];let line='';for(const word of String(text).split(/\s+/)){if(c.measureText((line+' '+word).trim()).width>maxWidth&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);if(lines.length<=maxLines&&lines.length*size*1.2<=maxHeight)break;}
  lines=lines.slice(0,maxLines);if(!lines.length)return;const lh=size*1.2;lines.forEach((line,i)=>{while(c.measureText(line).width>maxWidth&&line.length>1)line=line.slice(0,-2)+'…';c.fillText(line,300,cy+(i-(lines.length-1)/2)*lh,maxWidth);});
 }
 textBox(name||'Personagem',side==='front'?793:610,settings.fontSize,side==='front'?260:360,54,2);
 if(side==='back'&&settings.subtitle)textBox(settings.subtitle,690,22,340,100,4);
 return canvas;
}
export function characterCardMarkup(item,kind='characters'){return `<article class="character-list-card" data-character="${e(item.id)}" data-kind="${kind}"><button type="button" class="fantasy-card list-fantasy-card" aria-label="Virar carta de ${e(item.name)}" aria-pressed="false"><span class="card-flipper"><canvas class="card-face card-front" data-list-face="front" aria-label="Frente da carta de ${e(item.name)}"></canvas><canvas class="card-face card-back" data-list-face="back" aria-label="Verso da carta de ${e(item.name)}"></canvas></span></button><div class="character-list-caption"><h2>${e(item.name)}</h2><small>${e(item.role||(kind==='bestiary'?'Criatura':'Personagem'))} · ${e(item.species||'Espécie não definida')}</small></div><div class="character-list-actions"><button type="button" data-customize-card="${e(item.id)}">✧ Personalizar</button><button type="button" data-entity="${e(item.id)}" data-kind="${kind}">Abrir ficha ↗</button></div></article>`;}
export function mountSavedCards(container,items){for(const item of items){const card=[...container.querySelectorAll('[data-character]')].find(el=>el.dataset.character===item.id);if(!card)continue;const settings=cardSettings(item);for(const side of ['front','back']){const canvas=card.querySelector(`[data-list-face=${side}]`);drawCard(canvas,settings[side],item.name,side,600).catch(()=>{canvas.setAttribute('aria-label','Imagem indisponível. Use Personalizar para substituir.');});}const flip=card.querySelector('.list-fantasy-card');flip.onclick=()=>{const back=card.classList.toggle('list-card-back');flip.setAttribute('aria-pressed',String(back));};card.querySelector('[data-customize-card]').onclick=()=>card.dispatchEvent(new CustomEvent('customize-character-card',{bubbles:true,detail:{id:item.id,kind:card.dataset.kind}}));}}
export function openCharacterCard(item,{modal,save,notify}){
 const settings=cardSettings(item);let side='front',name=item.name,revision=0,alive=true;
 const range=(key,label,min,max,step)=>`<label>${label}<input type="range" name="${key}" min="${min}" max="${max}" step="${step}" aria-label="${label}"><output data-output="${key}"></output></label>`;
 modal(item.cardKind==='bestiary'?'Sua carta de criatura':'Sua carta de personagem',`<div class="character-card-editor"><section class="character-card-preview"><div class="card-face-tabs"><button type="button" data-card-side="front">Frente</button><button type="button" data-card-side="back">Verso</button></div><button type="button" class="fantasy-card" aria-label="Virar carta"><span class="card-flipper"><canvas class="card-face card-front" data-card-canvas="front"></canvas><canvas class="card-face card-back" data-card-canvas="back"></canvas></span></button><p class="help">Clique na carta para virar · Prévia em tempo real</p><div class="card-export-buttons"><button type="button" class="button ghost" data-export-card="front">↓ Frente PNG</button><button type="button" class="button ghost" data-export-card="back">↓ Verso PNG</button></div><small>PNG · 1600 × 2400 pixels por face</small><p role="status" id="cardStatus"></p></section><section class="character-card-controls"><label>Nome da carta<input name="cardName" value="${e(item.name)}" maxlength="80"></label><h3 id="cardSideTitle">Personalizar frente</h3><div class="card-color-control"><label>Cor de fundo<input type="color" name="background" aria-label="Cor de fundo da carta"></label><input name="backgroundHex" aria-label="HEX do fundo" pattern="#[0-9a-fA-F]{6}" maxlength="7"></div><div class="card-color-presets">${['#164b39','#18382e','#203956','#443e62','#f3e8cf','#532c38','#171e24'].map(c=>`<button type="button" data-card-color="${c}" style="background:${c}" aria-label="Fundo ${c}"></button>`).join('')}</div><label>Moldura<select name="frame"><option value="arabesque">Arabescos dourados</option><option value="celestial">Estrela dourada</option><option value="none">Sem moldura</option></select></label><h3>Imagem</h3><label class="button ghost card-upload-label">Carregar / substituir imagem<input type="file" name="portrait" accept="image/*"></label><button type="button" class="text-link" id="removeCardImage">Remover imagem desta face</button>${range('scale','Tamanho da imagem',.5,2,.05)}${range('zoom','Zoom',1,3,.05)}${range('x','Posição horizontal',-100,100,1)}${range('y','Posição vertical',-100,100,1)}<button type="button" class="text-link" id="resetCardPosition">Centralizar imagem</button><h3>Texto</h3><div class="card-color-control"><label>Cor do texto<input type="color" name="textColor" aria-label="Cor do texto da carta"></label><input name="textHex" aria-label="HEX do texto" pattern="#[0-9a-fA-F]{6}" maxlength="7"></div>${range('fontSize','Tamanho do nome',24,70,1)}<label>Legenda / informações do verso<textarea name="cardSubtitle" rows="3" maxlength="220"></textarea></label><p class="help">As cores, a imagem e a moldura são independentes em cada face. Use Salvar carta para guardar as alterações.</p></section></div>`,()=>{if(!name.trim())throw Error('Informe o nome do personagem.');item.name=name.trim();item.cardAppearance=settings;save();notify('Carta salva.');},{submit:'Salvar carta'});
 const root=document.querySelector('.character-card-editor'),form=root.closest('form'),dialog=root.closest('dialog'),$=s=>root.querySelector(s),status=$('#cardStatus');
 dialog.addEventListener('close',()=>{alive=false;revision++;},{once:true});
 async function paint(){const request=++revision;try{const canvases=await Promise.all(['front','back'].map(async key=>{const canvas=document.createElement('canvas');await drawCard(canvas,settings[key],name,key);return [key,canvas];}));if(!alive||request!==revision)return;for(const [key,canvas] of canvases){const target=$(`[data-card-canvas=${key}]`);target.width=canvas.width;target.height=canvas.height;target.getContext('2d').drawImage(canvas,0,0);}}catch(error){if(alive&&request===revision)status.textContent=error.message;}}
 function sync(){const cfg=settings[side];root.dataset.side=side;$('#cardSideTitle').textContent='Personalizar '+(side==='front'?'frente':'verso');root.querySelectorAll('[data-card-side]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cardSide===side)));for(const key of ['background','textColor','frame','scale','zoom','x','y','fontSize'])root.querySelector(`[name=${key}]`).value=cfg[key];root.querySelector('[name=backgroundHex]').value=cfg.background;root.querySelector('[name=textHex]').value=cfg.textColor;root.querySelector('[name=cardSubtitle]').value=cfg.subtitle;root.querySelectorAll('[data-output]').forEach(o=>o.value=cfg[o.dataset.output]);paint();}
 root.querySelectorAll('[data-card-side]').forEach(b=>b.onclick=()=>{side=b.dataset.cardSide;sync();});$('.fantasy-card').onclick=()=>{side=side==='front'?'back':'front';sync();};
 root.addEventListener('input',ev=>{const key=ev.target.name,cfg=settings[side];if(key==='cardName')name=ev.target.value;else if(key==='cardSubtitle')cfg.subtitle=ev.target.value;else if(['backgroundHex','textHex'].includes(key)){if(!/^#[0-9a-f]{6}$/i.test(ev.target.value))return;cfg[key==='backgroundHex'?'background':'textColor']=ev.target.value;root.querySelector(`[name=${key==='backgroundHex'?'background':'textColor'}]`).value=ev.target.value;}else if(['background','textColor'].includes(key)){cfg[key]=ev.target.value;root.querySelector(`[name=${key==='background'?'backgroundHex':'textHex'}]`).value=ev.target.value;}else if(['scale','zoom','x','y','fontSize'].includes(key)){cfg[key]=+ev.target.value;root.querySelector(`[data-output=${key}]`).value=cfg[key];}else return;paint();});
 root.querySelector('[name=frame]').onchange=ev=>{settings[side].frame=ev.target.value;paint();};root.querySelectorAll('[data-card-color]').forEach(b=>b.onclick=()=>{settings[side].background=b.dataset.cardColor;sync();});
 root.querySelector('[name=portrait]').onchange=async ev=>{const file=ev.target.files[0],face=side;if(!file)return;try{const src=await imageFile(file);if(!alive)return;settings[face].image=src;sync();}catch(error){status.textContent=error.message;}finally{ev.target.value='';}};
 $('#removeCardImage').onclick=()=>{settings[side].image='';paint();};$('#resetCardPosition').onclick=()=>{Object.assign(settings[side],{x:0,y:0,zoom:1,scale:1});sync();};
 root.querySelectorAll('[data-export-card]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await document.fonts.ready;const key=button.dataset.exportCard,canvas=await drawCard(document.createElement('canvas'),settings[key],name,key,1600),blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Falha ao exportar PNG.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aethra-${name.replace(/[^\p{L}\p{N}-]/gu,'-').slice(0,60)}-${key==='front'?'frente':'verso'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status.textContent='PNG exportado · 1600 × 2400 pixels.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});sync();
}
